async function r(a,t={}){const e=await fetch(a,{cache:"no-store",...t}),n=await e.text();let i;try{i=n?JSON.parse(n):{}}catch{throw new Error(`API returned invalid JSON (${e.status})`)}if(!e.ok)throw new Error(i.error||e.statusText);return i}async function s(){const a=await r("/api/map");if(!Array.isArray(a.origin)||!a.width||!a.height||!a.resolution)throw new Error("Map metadata unavailable");return a}const o=()=>r("/api/bounds");async function l(){const a=await r("/api/tasks/delivery");if(!Array.isArray(a.vehicles)||!Array.isArray(a.stations)||typeof a.online!="boolean")throw new Error("Delivery fleet unavailable");return a}async function c(){const a=await r("/api/health");if(!a.ok||!a.services||!Array.isArray(a.vehicles))throw new Error("System health unavailable");return a}async function y(a){const t=await r("/api/simulation/faults",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(a)});if(!t.simulation_only||!Array.isArray(t.active))throw new Error("Simulation fault control unavailable");return t}async function u(a){const t=await r(`/api/state?${new URLSearchParams(a)}`);if(!Array.isArray(t.latest)||!Array.isArray(t.density))throw new Error("Traffic history unavailable");return t}export{s as a,l as b,o as c,u as d,c as g,y as s};
